CREATE OR REPLACE FUNCTION public.caracteristicas_antesinseriratualizar()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare vp record;
        vf record;
BEGIN

   IF TG_OP = 'INSERT' THEN 
	    IF NEW.Codigo IS NULL THEN 
			NEW.Codigo:= Caracteristicas_ProximoCodigo();
        END IF;

        IF NEW.CodigoVisual IS NULL THEN 
			NEW.CodigoVisual:= CAST(NEW.Codigo AS VARCHAR);
        END IF;

   ELSE IF NOT NEW.VeioDaTriggerProdutos THEN
		
   
		IF OLD.ForaLinha IS NULL AND
           NEW.ForaLinha IS NOT NULL
        THEN UPDATE Produtos
                SET ForaLinha = NEW.ForaLinha,
                    VeioDaTriggerCaracteristicas = TRUE
                WHERE Caracteristica = NEW.Codigo AND ForaLinha IS NULL;
        END IF;

        IF OLD.ForaLinha IS NOT NULL AND
           NEW.ForaLinha IS NULL
        THEN UPDATE Produtos
                SET ForaLinha = NULL,
                    VeioDaTriggerCaracteristicas = TRUE
                WHERE Caracteristica = NEW.Codigo AND ForaLinha IS NOT NULL;
        END IF;

        IF OLD.Inativo IS NULL AND
           NEW.Inativo IS NOT NULL
        THEN UPDATE Produtos
                SET Inativo = NEW.Inativo,
                    VeioDaTriggerCaracteristicas = TRUE
                WHERE Caracteristica = NEW.Codigo AND Inativo IS NULL;
         END IF;

         IF OLD.Inativo IS NOT NULL AND
            NEW.Inativo IS NULL
         THEN UPDATE Produtos
                 SET Inativo = NULL,
                    VeioDaTriggerCaracteristicas = TRUE
                 WHERE Caracteristica = NEW.Codigo AND Inativo IS NOT NULL;
         END IF;

         --------- Grupo foi acrescentado aos movimentos para permitir a emiss�o
                -- do relat�rio do Resumo de Estoque pela KRAH-ICE
        /* IF NEW.Grupo <> OLD.Grupo 
         THEN FOR vP IN SELECT * FROM Produtos p
                           WHERE p.Caracteristica = NEW.Codigo
              LOOP FOR vF IN SELECT filial FROM estoques WHERE produto=vp.Codigo
                   LOOP INSERT INTO Movimentos (Produto, Filial, Data, TipoMovimento, Quantidade, Valor)
                               VALUES (vP.Codigo, vF.filial, CURRENT_DATE, 'AGM', 0, 0);
                   END LOOP;
              END LOOP;
         END IF;*/
		 
	END IF;

   END IF;
   
   IF NEW.especial IS NULL THEN
      NEW.especial:=false;
   END IF;
   
   IF NEW.icmsmodalidade IS NULL THEN
      NEW.icmsmodalidade:=3;
   END IF;
   
   NEW.VeioDaTriggerProdutos=false;
   NEW.Data:= COALESCE(NEW.Data, CURRENT_DATE);

   RETURN NEW;
END;
$function$

