CREATE OR REPLACE FUNCTION public.movimentos_antesdeletar()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
   vEhComposto BOOLEAN;
   vComposto   BIGINT;
BEGIN

   SELECT Composto INTO vEhComposto
      FROM Caracteristicas
      WHERE Codigo = (SELECT Caracteristica
                         FROM Produtos
                         WHERE Codigo = OLD.Produto);

   IF vEhComposto
   THEN INSERT INTO MovimentosDeletando (Numero)
               VALUES (OLD.Numero);

        ----------------------------------------- Se o produto for  composto, os
        DELETE FROM Movimentos                 -- movimentos de seus componentes
           WHERE CmpMovimento = OLD.Numero;    -- tamb�m ser�o eliminados

        ------------------------------------------- Elimina��o das movimenta�es
        DELETE FROM Movimentos                   -- geradas por estoque negativo
           WHERE NEGMovimento = OLD.Numero;

        ------------------------------------------- Elimina��o das movimenta�es
        DELETE FROM Movimentos                   -- geradas por transfer�ncias
           WHERE TRFMovimento = OLD.Numero;


   ---------------------------------- Est�-se tentando eliminar uma movimenta��o
                                   -- de componente diretamente, ao inv�s de ser
                                   -- atrav�s do produto composto?
   ELSE IF OLD.CmpMovimento IS NOT NULL THEN
           IF OLD.CmpMovimento <>
              COALESCE((SELECT Numero FROM MovimentosDeletando), 0)
           THEN SELECT Produto INTO vComposto
                   FROM Movimentos
                   WHERE Numero = OLD.CmpMovimento;

                RAISE EXCEPTION 'A movimenta��o % do produto % na filial % � origin�ria do produto %',
                                OLD.Numero, OLD.Produto, OLD.Filial, vComposto;
            END IF;
        END IF;
   END IF;

   RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION public.movimentos_antesinseriratualizar()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE --------------------------------------------------------------------------------------------
                                -- 23jul15 Alterada para que atualize em todas as filiais o valor de
                                --         PrecoComICMS e PrecoSemICMS. Antes, s� estava atualizando
                                --         o valor da UltimaCompra e Data.
                                -- 25ago15 Na altera�es de datas, gerar-se-� novo LANCTO.
                                
                                -- 18mar20 Acerto do valor movimentado quando o movimento foi gerado
                                --         a partir do produto composto.                               
   rAbaixo         RECORD;
   rAnterior       RECORD;
   rCaracteristica RECORD;
   rComponente     RECORD;
   rEstoque        RECORD;
   rSeguinte       RECORD;
   rTipoMovto      RECORD;
   rComposto       RECORD;
   vAlterouEstoque BOOLEAN;
   vAntFinanceiro  NUMERIC(11,2);
   vCodigoVisual   VARCHAR;
   vComLote        BOOLEAN;
   vCustoMedio     NUMERIC(11,2);
   vCustoOriginal  NUMERIC(11,3);
   vDataAnterior   VARCHAR;
   vDaData         DATE;
   vDataAtual      VARCHAR;
   vDeveExecutar   BOOLEAN;
   vDoLancto       INTEGER;
   vMsg            VARCHAR;
   vNrAnterior     INTEGER;
   vOpera          CHAR;
   vTotalAnterior  NUMERIC(11,3);
   vTotalEstoque   NUMERIC(11,3);
BEGIN
   IF NEW.UsuarioLogado IS NULL
   THEN NEW.UsuarioLogado:= (SELECT Codigo FROM Usuarios WHERE UseName = CURRENT_USER);
   END IF;
   NEW.NaoProcessarTRIGGERSDepois:= NEW.NaoProcessarTRIGGERS;
   IF NOT NEW.NaoProcessarTRIGGERS
   THEN
        vComLote:= (SELECT c.GerenciarLoteeValidade ---------------- Produto exige lote? -- 04out2021
                       FROM Caracteristicas c
                       WHERE c.Codigo = (SELECT p.Caracteristica 
                                            FROM Produtos p
                                            WHERE p.Codigo = NEW.Produto));
        IF vComLote AND (NEW.LoteProduto IS NULL)
        THEN RAISE EXCEPTION 'O produto % exige lote, mas o lote n�o foi informado', NEW.Produto;
        END IF; -------------------------------------------------------------------------- 04out2021
                                    
        IF TG_OP = 'UPDATE'
        THEN IF NEW.ValorUltimaCompra IS NULL AND
                OLD.ValorUltimaCompra IS NOT NULL
             THEN RAISE EXCEPTION 'O valor da �ltima compra n�o era NULL em N: %, P: %, F: %, D: %, L: %',
                                   NEW.Numero, NEW.Produto, NEW.Filial, NEW.Data, NEW.Lancto;
             END IF;
/* 25ago15 */
             IF OLD.Data <> NEW.Data ------------------------ Se houve altera��o de data, gerar-se-a
             THEN SELECT MAX(Lancto) INTO vNrAnterior      -- um novo NEW.Lancto
                     FROM  Movimentos
                     WHERE Produto = NEW.Produto AND
                           Filial  = NEW.Filial  AND
                           Data    = NEW.Data;
                  NEW.Lancto:= COALESCE(vNrAnterior, 0) + 1;
             END IF;
/* 25ago15 */
        END IF;

        NEW.Quantidade = COALESCE(NEW.Quantidade,0);
        vDeveExecutar:= TG_OP = 'INSERT';
        IF TG_OP = 'UPDATE'
        THEN vDeveExecutar:= NEW.Data <= OLD.Data;
        END IF;
        IF vDeveExecutar
        THEN IF NEW.Numero IS NULL -------------------------- N�mero s� dever� ser NULL em inser�es
             THEN NEW.Numero := Movimentos_ProximoNumero();
             ELSE IF TG_OP = 'INSERT'
                  THEN SELECT MAX(Numero) INTO vNrAnterior
                          FROM  Movimentos
                          WHERE Produto = NEW.Produto AND
                                Filial  = NEW.Filial;
                       IF vNrAnterior > NEW.Numero AND
                          NEW.TipoMovimento <> 'SEF'
                       THEN RAISE EXCEPTION 'Houve problemas na transa��o. Por favor, tente novamente';
                       END IF;
                  END IF;
             END IF;

             IF TG_OP = 'INSERT' ---------------------- Verifica��o do tipo de movimento na inser��o
             THEN SELECT Operacao, Transferencia,
                         COALESCE(QuandoEstoqueNegativo,FALSE) AS
                                  QuandoEstoqueNegativo INTO rTipoMovto
                     FROM TiposMovimentos
