CREATE OR REPLACE FUNCTION public.replicacao_set_timestamps_fn()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.created_at := COALESCE(NEW.created_at, clock_timestamp());
    NEW.updated_at := COALESCE(NEW.updated_at, NEW.created_at);
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    NEW.created_at := OLD.created_at;

    IF (to_jsonb(NEW) - 'created_at' - 'updated_at' - 'cloud_row_version')
       IS DISTINCT FROM
       (to_jsonb(OLD) - 'created_at' - 'updated_at' - 'cloud_row_version') THEN
      NEW.updated_at := clock_timestamp();
    ELSE
      NEW.updated_at := OLD.updated_at;
    END IF;

    RETURN NEW;
  END IF;

  RETURN NEW;
END;
