 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  ign CONSTANT text[] := ARRAY[
    'created_at', 'updated_at', 'ultimaalteracao',
    'datahoraconferenciacadastro', 'cloud_row_version'
  ];
  r record;
  diff jsonb := '{}'::jsonb;
  o_txt text;
  n_txt text;
  app_uid_text text;
  app_uid bigint;
  app_login text;
  app_name text;
  app_src text;
  app_req text;
  db_user text;
BEGIN
  db_user := CURRENT_USER::text;

  BEGIN
    app_uid_text := current_setting('app.user_id', true);
  EXCEPTION WHEN OTHERS THEN
    app_uid_text := '';
  END;
  IF app_uid_text IS NULL OR btrim(app_uid_text) = '' THEN
    app_uid := NULL;
  ELSE
    BEGIN
      app_uid := app_uid_text::bigint;
    EXCEPTION WHEN OTHERS THEN
      app_uid := NULL;
    END;
  END IF;

  BEGIN
    app_login := NULLIF(btrim(current_setting('app.user_login', true)), '');
  EXCEPTION WHEN OTHERS THEN
    app_login := NULL;
  END;
  BEGIN
    app_name := NULLIF(btrim(current_setting('app.user_name', true)), '');
  EXCEPTION WHEN OTHERS THEN
    app_name := NULL;
  END;
  BEGIN
    app_src := NULLIF(btrim(current_setting('app.source', true)), '');
  EXCEPTION WHEN OTHERS THEN
    app_src := NULL;
  END;
  BEGIN
    app_req := NULLIF(btrim(current_setting('app.request_id', true)), '');
  EXCEPTION WHEN OTHERS THEN
    app_req := NULL;
  END;

  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.caracteristicas_log_new (
      caracteristica_codigo, trigger_mode, trigger_tuple, trigger_user_db,
      app_user_id, app_user_login, app_user_name, app_source, request_id, dados
    ) VALUES (
      NEW.codigo, 'INSERT', 'new', db_user,
      app_uid, app_login, app_name, app_src, app_req, row_to_json(NEW)::jsonb
    );
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    INSERT INTO public.caracteristicas_log_new (
      caracteristica_codigo, trigger_mode, trigger_tuple, trigger_user_db,
      app_user_id, app_user_login, app_user_name, app_source, request_id, dados
    ) VALUES (
      OLD.codigo, 'DELETE', 'old', db_user,
      app_uid, app_login, app_name, app_src, app_req, row_to_json(OLD)::jsonb
    );
    RETURN OLD;
  END IF;

  FOR r IN
    SELECT a.attname AS col
    FROM pg_attribute a
    WHERE a.attrelid = 'public.caracteristicas'::regclass
      AND a.attnum > 0
      AND NOT a.attisdropped
  LOOP
    IF r.col = ANY (ign) THEN
      CONTINUE;
    END IF;
    EXECUTE format('SELECT ($1).%I::text, ($2).%I::text', r.col, r.col) USING OLD, NEW INTO o_txt, n_txt;
    IF o_txt IS DISTINCT FROM n_txt THEN
      diff := diff || jsonb_build_object(
        r.col,
        jsonb_build_object('old', to_jsonb(o_txt), 'new', to_jsonb(n_txt))
      );
    END IF;
  END LOOP;

  IF diff <> '{}'::jsonb THEN
    INSERT INTO public.caracteristicas_log_new (
      caracteristica_codigo, trigger_mode, trigger_tuple, trigger_user_db,
      app_user_id, app_user_login, app_user_name, app_source, request_id, dados
    ) VALUES (
      NEW.codigo, 'UPDATE', 'diff', db_user,
      app_uid, app_login, app_name, app_src, app_req, diff
    );
  END IF;

  RETURN NEW;
END;
$function$

