CREATE OR REPLACE FUNCTION public.atualizavfornecedores()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare

  vpessoatipo char;

  vpessoanumero varchar(14);

  vcnpj varchar(14);

  vinscricaomunicipal varchar(20);

  vtipo char;

  vinscrest fornecedores.inscricaoestadual%TYPE;

  vfoneramal varchar(10);

  vempddd    int2;

  vempfone integer;

  vempramal char(10);

  vempresa varchar(40);

  vgrupofornecedor integer;

  vcivil char(1);

  vmarkup numeric(8,2);

  vconjuge integer;

  vconceito int2;

  vcodigo bigint;

  venderecoalterado date;

  vnome varchar;

  vrazao varchar(60);

  vemail varchar(128);

  vnosimples boolean;
  
  vestrangeiro boolean;

  vsexo varchar(1);

  vhistoricocontabil integer;

begin



  if TG_RELNAME = 'clientes' then

    vtipo := 'C';

    if TG_OP <> 'DELETE' then

      vpessoanumero      := new.pessoanumero;

	  vinscricaomunicipal:= new.inscricaomunicipal;

      vpessoatipo        := new.pessoatipo;

      vinscrest          := new.iddocumento;

      vfoneramal         := new.foneramal;

      vempfone           := new.empfonenumero;

      vempddd            := new.empfoneddd;

      vempramal          := new.empfoneramal;

      vempresa           := new.empresa;

      vcivil             := new.civil;

      vconjuge           := new.conjuge;

      vconceito          := new.conceito;

      venderecoalterado  := new.enderecoalterado;

      vnome              := (case when btrim(coalesce(new.apelido,''))<>'' then new.apelido else new.nome end);

      vrazao             := new.nome;

      vemail             := new.email;

      vnosimples         := new.nosimples;
	  
	  vestrangeiro       := new.estrangeiro;

      vmarkup            := new.markup;

      vsexo              := new.sexo;

      vhistoricocontabil := new.historicocontabil;	

    end if;

  else

    vcivil := 'O';

    if TG_RELNAME = 'fornecedores' then

      vtipo  := 'F';

      if TG_OP <> 'DELETE' then

        vpessoanumero      := new.pessoanumero;

		vinscricaomunicipal:= new.inscricaomunicipal;

        vpessoatipo        := new.pessoatipo;

        vinscrest          := new.inscricaoestadual;

        vempfone           := new.faxnumero;

        vempddd            := new.faxddd;

        vgrupofornecedor   := new.grupofornecedor;

        vmarkup            := new.markup;

        vconceito          := new.conceito;

        venderecoalterado  := new.enderecoalterado;

        vnome              := (case when btrim(coalesce(new.nome,''))<>'' then new.nome else new.razao end);

        vrazao             := new.razao;

        vemail             := new.email;

        vnosimples         := new.nosimples;
		
		vestrangeiro       := new.estrangeiro;

        vsexo              := 'E';

        vhistoricocontabil := new.historicocontabil;

      end if;

    else

      if TG_RELNAME = 'filiais' then

        vtipo  := 'L';

        if TG_OP <> 'DELETE' then

          vpessoanumero     := new.cnpj;

		  vinscricaomunicipal:= new.inscricaomunicipal;

          vpessoatipo       := 'J';

          vinscrest         := new.inscricaoestadual;

          vempfone          := new.faxnumero;

          vempddd           := new.faxddd;

          vnome             := new.razao;

          vrazao            := new.razao;

          vemail            := null;

          vnosimples        := false;
		  
		  vestrangeiro      := false;

          vsexo              := 'E';

          vhistoricocontabil := null;

        end if;

      end if;

    end if;

  end if;



  if TG_OP = 'INSERT' then

    if (vpessoanumero <> '') AND (vpessoanumero <> '0') then

           vcnpj:= cast(substring(vpessoanumero from 1 for length(vpessoanumero)-2) as varchar);

      else vcnpj:= '';

    end if;

    insert into vfornecedores (codigo,

                               nome,

			       razao,

                               pessoatipo,

                               pessoanumero,

                               cnpj,

                               inscricaoestadual,

                               rua,

                               numero,

                               complemento,

                               cidade,

                               bairro,

                               cep,

                               estado,

                               tipo,

                               fonenumero,

                               foneddd,

                               foneramal,

                               fonenumeroempresa,

                               fonedddempresa,

                               foneramalempresa,

                               empresa,

                               grupofornecedor,

                               civil,

                               markup,

                               conjuge,

                               conceito,

			       enderecoalterado,

			       email,

			       debito,

			       credito,

			       nosimples,
				   
				   estrangeiro,

			       contribicms,

      	       sexo,

	             suframa,

	             historicocontabil,

				 inscricaomunicipal

                )



    values (new.codigo,

            vnome,

	    vrazao,

            vpessoatipo,

            vpessoanumero,

            vcnpj,

            vinscrest,

            new.rua,

            new.numero,

            new.complemento,

            new.cidade,

            new.bairro,

            new.cep,

            new.estado,

            vtipo,

            new.fonenumero,

            new.foneddd,

            vfoneramal,

            vempfone,

            vempddd,

            vempramal,

            vempresa,

            vgrupofornecedor,

            vcivil,

            vmarkup,

            vconjuge,

            vconceito,

	    venderecoalterado,

	    vemail,

	    new.debito,

	    new.credito,

	    vnosimples,
		
		vestrangeiro,

	    new.contribicms,

       vsexo,

       new.suframa,

       vhistoricocontabil,

	   vinscricaomunicipal

	    );

  else

    vcodigo := old.codigo;

    if TG_OP = 'DELETE' then

      if TG_RELNAME = 'clientes' then

        delete from vfornecedores where codigo = old.codigo and tipo = 'C';

      else

        if TG_RELNAME = 'fornecedores' then

          delete from vfornecedores where codigo = old.codigo and tipo = 'F';

        else

          if TG_RELNAME = 'filiais' then

            delete from vfornecedores where codigo = old.codigo and tipo = 'L';

          end if;

        end if;

      end if;

    else

      if TG_OP = 'UPDATE' then

        if (vpessoanumero <> '') and (vpessoanumero <> '0') then

               vcnpj:= cast(substring(vpessoanumero from 1 for length(vpessoanumero)-2) as varchar);

          else vcnpj:= '';

        end if;





        update vfornecedores set nome              = vnome,

	                         razao             = vrazao,

                                 pessoatipo        = vpessoatipo,

                                 pessoanumero      = vpessoanumero,

                                 cnpj              = vcnpj,

                                 inscricaoestadual = vinscrest,

                                 rua               = new.rua,

                                 numero            = new.numero,

                                 complemento       = new.complemento,

                                 cidade            = new.cidade,

                                 bairro            = new.bairro,

                                 cep               = new.cep,

                                 estado            = new.estado,

                                 fonenumero        = new.fonenumero,

                                 foneddd           = new.foneddd,

                                 foneramal         = vfoneramal,

                                 fonenumeroempresa = vempfone,

                                 fonedddempresa    = vempddd,

                                 foneramalempresa  = vempramal,

                                 empresa           = vempresa,

                                 grupofornecedor   = vgrupofornecedor,

                                 civil             = vcivil,

                                 markup            = vmarkup,

                                 conjuge           = vconjuge,

                                 conceito          = vconceito,

                                 enderecoalterado  = venderecoalterado,

                                 email             = vemail,

                                 debito            = new.debito,

                                 credito           = new.credito,

                                 nosimples         = vnosimples,
								 
								 estrangeiro       = vestrangeiro,

                                 contribicms       = new.contribicms,

                                 sexo              = vsexo,

                                 suframa           = new.suframa,

                                 historicocontabil = vhistoricocontabil,

								 inscricaomunicipal = vinscricaomunicipal

        where codigo = vcodigo and tipo = vtipo;

      end if;

    end if;

  end if;

  return new;

end;
$function$

CREATE OR REPLACE FUNCTION public.filiais_log()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    diffs jsonb := '{}'::jsonb;
    field text;
    old_row jsonb;
    new_row jsonb;
BEGIN
    IF (TG_OP = 'UPDATE') THEN
        old_row := to_jsonb(OLD);
        new_row := to_jsonb(NEW);

        FOR field IN SELECT column_name FROM information_schema.columns
                     WHERE table_name = 'filiais'
        LOOP
            IF new_row -> field IS DISTINCT FROM old_row -> field THEN
                diffs := diffs || jsonb_build_object(field, jsonb_build_object(
                    'old', old_row -> field,
                    'new', new_row -> field
                ));
            END IF;
        END LOOP;

        IF diffs <> '{}'::jsonb THEN
            INSERT INTO filiais_log (
                codigo, trigger_mode, trigger_user, trigger_changed, trigger_tuple, dados
            ) VALUES (
                NEW.codigo, TG_OP, current_user, now(), 'diff', diffs
            );
        END IF;

    ELSIF (TG_OP = 'DELETE') THEN
        INSERT INTO filiais_log (
            codigo, trigger_mode, trigger_user, trigger_changed, trigger_tuple, dados
        ) VALUES (
            OLD.codigo, TG_OP, current_user, now(), 'old', to_jsonb(OLD)
        );

    ELSIF (TG_OP = 'INSERT') THEN
        INSERT INTO filiais_log (
            codigo, trigger_mode, trigger_user, trigger_changed, trigger_tuple, dados
        ) VALUES (
            NEW.codigo, TG_OP, current_user, now(), 'new', to_jsonb(NEW)
        );
    END IF;

    RETURN NULL;
END;
$function$

