CREATE OR REPLACE FUNCTION public.movimentos_antesdeletar()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
   vEhComposto BOOLEAN;
   vComposto   BIGINT;
BEGIN

   SELECT Composto INTO vEhComposto
      FROM Caracteristicas
      WHERE Codigo = (SELECT Caracteristica
                         FROM Produtos
                         WHERE Codigo = OLD.Produto);

   IF vEhComposto
   THEN INSERT INTO MovimentosDeletando (Numero)
               VALUES (OLD.Numero);

        ----------------------------------------- Se o produto for  composto, os
        DELETE FROM Movimentos                 -- movimentos de seus componentes
           WHERE CmpMovimento = OLD.Numero;    -- tamb�m ser�o eliminados

        ------------------------------------------- Elimina��o das movimenta�es
        DELETE FROM Movimentos                   -- geradas por estoque negativo
           WHERE NEGMovimento = OLD.Numero;

        ------------------------------------------- Elimina��o das movimenta�es
        DELETE FROM Movimentos                   -- geradas por transfer�ncias
           WHERE TRFMovimento = OLD.Numero;


   ---------------------------------- Est�-se tentando eliminar uma movimenta��o
                                   -- de componente diretamente, ao inv�s de ser
                                   -- atrav�s do produto composto?
   ELSE IF OLD.CmpMovimento IS NOT NULL THEN
           IF OLD.CmpMovimento <>
              COALESCE((SELECT Numero FROM MovimentosDeletando), 0)
           THEN SELECT Produto INTO vComposto
                   FROM Movimentos
                   WHERE Numero = OLD.CmpMovimento;

                RAISE EXCEPTION 'A movimenta��o % do produto % na filial % � origin�ria do produto %',
                                OLD.Numero, OLD.Produto, OLD.Filial, vComposto;
            END IF;
        END IF;
   END IF;

   RETURN OLD;
END;
