  IF diff <> '{}'::jsonb THEN
    INSERT INTO public.pedidosfiliais_log_new (
      pedido_filial_codigo, trigger_mode, trigger_tuple, trigger_user_db,
      app_user_id, app_user_login, app_user_name, app_source, request_id, dados
    ) VALUES (
      codigo_ref, 'UPDATE', 'diff', db_user,
      app_uid, app_login, app_name, app_src, app_req, diff
    );
  END IF;

  RETURN NEW;
END;
